-- HOOP AGENTS -- the hoopltd.shop staff register, inserted per the owner's standing rule.
-- Source: SyscoPos Agents Register saved by Sipho 2026-08-15 (rows 1-100 of 1,046).
-- Safe to paste MORE THAN ONCE: the insert upserts on phone, so a re-paste (or the
-- next 100-row batch) updates rather than duplicates. One transaction, two statements.
-- Branch here is SyscoPos's own region label; it does NOT create rows in teams --
-- the calling deck's teams stay driven by the Watu uploads.

create table if not exists hoop_agents (
  phone            text primary key,      -- 0-format as SyscoPos stores it; join to sales by pnorm
  name             text not null,
  national_id      text,
  email            text,
  kin_name         text,                  -- next of kin: the agent-side "guarantor" slot
  kin_phone        text,
  kin_relationship text,
  role             text,                  -- Country_Sales_Manager | Regional_Manager | Team_Leader | Field_Officer
  branch           text,                  -- SyscoPos region label (not our teams table)
  active           boolean default true,
  joined_date      date,
  updated_at       timestamptz default now()
);

on conflict (phone) do update set
  name = excluded.name, national_id = excluded.national_id, email = excluded.email,
  kin_name = excluded.kin_name, kin_phone = excluded.kin_phone,
  kin_relationship = excluded.kin_relationship, role = excluded.role,
  branch = excluded.branch, active = excluded.active, joined_date = excluded.joined_date,
  updated_at = now();
